# Let's manually examine the pairs to understand the transformations
inputs = ['ykyewa', 'xkbabz', 'vkyfck', 'izczaf', 'kdhi']
outputs = ['jijewa', 'eeibabz', 'viijzci', 'izczaf', 'idzji']

print("Input -> Output:")
for i in range(len(inputs)):
    print(f"{inputs[i]} -> {outputs[i]}")

# Let's look at each difference
print("\nDetailed differences:")
for i in range(len(inputs)):
    inp, outp = inputs[i], outputs[i]
    print(f"Index {i}: {inp} -> {outp}")

    # Find where they differ
    for j in range(max(len(inp), len(outp))):
        if j >= len(inp) or j >= len(outp) or inp[j] != outp[j]:
            print(f"  First difference at position {j}")
            if j < len(inp):
                print(f"  Input char: '{inp[j]}'")
            if j < len(outp):
                print(f"  Output char: '{outp[j]}'")
            break

